// 1. Obtener datos del disparador (con respaldo por si pruebas manualmente en el lienzo)
let triggerData = {};
try {
  const triggerNode = $('When Executed by Another Workflow');
  if (triggerNode && triggerNode.first()) {
    triggerData = triggerNode.first().json;
  }
} catch (e) {
  triggerData = $('When Executed by Another Workflow').first().json.chatInput;
}

// 2. Obtener destinos directamente del nodo de Google Sheets
const sheetItems = $('Google Sheets: Catálogo Destinos').all().map(i => i.json);
const contextoDestinos = JSON.stringify(sheetItems, null, 2);

// 3. Obtener políticas directamente del nodo Extract from File (nunca con $input)
const extractNode = $('Extract from File').first().json;
const contextoPoliticas = extractNode.data || extractNode.fileContent || '';

// 4. Retornar contexto unificado
return [{
  json: {
    ...triggerData,
    contextoRAG: `--- CATÁLOGO DE DESTINOS Y TARIFAS (Google Sheets) ---\n${contextoDestinos}\n\n--- POLÍTICAS OFICIALES Y REEMBOLSOS (Google Docs) ---\n${contextoPoliticas}`
  }
}];

