const response = $input.first().json;
let parsedOutput = {};
try {
  const rawText = response.candidates[0].content.parts[0].text;
  parsedOutput = JSON.parse(rawText);
} catch (e) {
  parsedOutput = {
    propuestaRespuesta: 'No sé. No dispongo de esa información en los registros actuales.',
    intencion: 'CONSULTA_GENERAL',
    requiereVentasSlack: false,
    fuentesCitadas: []
  };
}

const prevData = $('Consolidar Contexto RAG').first().json;

return [{
  json: {
    ...prevData,
    ...parsedOutput
  }
}];
